<?php require_once __DIR__.'/comman/auth.php'; $pageTitle="Games"; require __DIR__.'/comman/header.php'; require __DIR__.'/comman/sidebar.php'; ?><div class="content-wrapper"><section class="content-header"><div class="container-fluid"><div class="row mb-2"><div class="col-sm-8"><h1><?=h($pageTitle)?></h1></div></div><?php if($flash):?><div class="alert alert-<?=h($flash[0])?>"><?=h($flash[1])?></div><?php endif;?></div></section><section class="content"><div class="container-fluid"><?php $games=read_json(SITE_ROOT.'/data/games.json',[]);if(isset($_GET['delete'])){if(!hash_equals(csrf(),$_GET['csrf']??''))die('Invalid request');$slug=slugify($_GET['delete']);$games=array_values(array_filter($games,fn($g)=>($g['slug']??'')!==$slug));write_json(SITE_ROOT.'/data/games.json',$games);flash('success','Game removed from data.');redirect_admin('games.php');} ?><div class="card"><div class="card-header"><h3 class="card-title">All Games</h3><a href="add_game.php" class="btn btn-pink btn-sm float-right"><i class="fas fa-plus"></i> Add Game</a></div><div class="card-body table-responsive p-0"><table class="table table-hover text-nowrap"><thead><tr><th>Game</th><th>Category</th><th>Image</th><th>Status</th><th>Flags</th><th>Actions</th></tr></thead><tbody><?php foreach($games as $g):?><tr><td><b><?=h($g['name']??'')?></b><br><small><?=h($g['slug']??'')?></small></td><td><?=h($g['category']??'')?></td><td><?php if(!empty($g['image'])):?><img class="img-thumb" src="../<?=h(ltrim($g['image'],'/'))?>" onerror="this.style.display='none'"><?php endif;?></td><td><span class="badge badge-<?=!empty($g['status'])?'success':'secondary'?>"><?=!empty($g['status'])?'Active':'Hidden'?></span></td><td><?=!empty($g['featured'])?'⭐':''?> <?=!empty($g['popular'])?'🔥':''?> <?=!empty($g['new_game'])?'🆕':''?></td><td><a class="btn btn-sm btn-outline-primary" href="add_game.php?edit=<?=urlencode($g['slug']??'')?>">Edit</a> <a class="btn btn-sm btn-outline-danger" href="games.php?delete=<?=urlencode($g['slug']??'')?>&csrf=<?=h(csrf())?>" onclick="return confirm('Delete this game from data?')">Delete</a></td></tr><?php endforeach;?></tbody></table></div></div></div></section></div><?php require __DIR__.'/comman/footer.php'; ?>